import datetime

def run_journal_entry_testing_analytics(
    journal_entries: list = None,
    approval_threshold_usd: float = 100000.0
) -> dict:
    # ISA 240 / PCAOB AS 2401 Computerized Journal Entry Testing (JET) Anomaly Engine
    if journal_entries is None:
        journal_entries = [
            {"id": "JE-101", "user": "ap_clerk_1", "amount": 14238.45, "day": "Wednesday", "hour": 14, "desc": "Vendor payment batch #441", "debit": "Inventory", "credit": "AP"},
            {"id": "JE-102", "user": "cfo_exec", "amount": 1000000.00, "day": "Sunday", "hour": 23, "desc": "to reclass", "debit": "Prepaid Exp", "credit": "Cost of Sales"},
            {"id": "JE-103", "user": "gl_acct_2", "amount": 99500.00, "day": "Friday", "hour": 17, "desc": "Accrued legal retainer", "debit": "Legal Exp", "credit": "Accrued Liab"},
            {"id": "JE-104", "user": "it_admin_db", "amount": 450000.00, "day": "Saturday", "hour": 3, "desc": "system fix", "debit": "Software", "credit": "Cash"},
            {"id": "JE-105", "user": "billing_spec", "amount": 8452.10, "day": "Tuesday", "hour": 11, "desc": "Monthly SaaS billing", "debit": "AR", "credit": "Revenue"}
        ]

    flagged_entries = []
    for je in journal_entries:
        flags = []
        # 1. Executive or IT User Override Flag
        if any(role in je['user'].lower() for role in ['cfo', 'ceo', 'vp', 'it_admin', 'dba']):
            flags.append("HIGH_RISK_EXECUTIVE_OR_IT_USER")
        # 2. Weekend or Late Night Posting Flag (Saturday/Sunday or hours 20-6)
        if je['day'] in ['Saturday', 'Sunday'] or (je['hour'] >= 20 or je['hour'] <= 5):
            flags.append("UNUSUAL_POSTING_TIME_WEEKEND_OR_NIGHT")
        # 3. Round Number or Just-Below-Threshold Flag
        if je['amount'] >= 10000.0 and je['amount'].is_integer():
            flags.append("LARGE_ROUND_NUMBER_ENTRY")
        if approval_threshold_usd * 0.90 <= je['amount'] < approval_threshold_usd:
            flags.append("SPLIT_ENTRY_JUST_BELOW_SUPERVISORY_THRESHOLD")
        # 4. Vague or Suspicious Narrative
        if any(term in je['desc'].lower() for term in ['reclass', 'fix', 'plug', 'adjust', 'per cfo']):
            flags.append("SUSPICIOUS_OR_VAGUE_NARRATIVE_MEMO")

        if flags:
            flagged_entries.append({
                'entry_id': je['id'],
                'user': je['user'],
                'amount_usd': je['amount'],
                'narrative': je['desc'],
                'risk_flags': flags,
                'mandatory_forensic_audit_action': "INSPECT_SOURCE_VOUCHER_AND_BOARD_AUTHORIZATION"
            })

    return {
        'total_entries_interrogated': len(journal_entries),
        'high_risk_anomalies_flagged': len(flagged_entries),
        'flagged_journal_entries': flagged_entries
    }

jet_audit = run_journal_entry_testing_analytics()
print("=== ISA 240 Automated Journal Entry Testing (JET) Report ===")
print(f"Total Journal Entries Audited:   {jet_audit['total_entries_interrogated']}")
print(f"High-Risk Anomalies Detected:    {jet_audit['high_risk_anomalies_flagged']}")
print("\nFlagged High-Risk Journal Entries Detail:")
for je in jet_audit['flagged_journal_entries']:
    print(f" - ID: {je['entry_id']:6} | User: {je['user']:12} | Amount: ${je['amount_usd']:>10,.2f} | "
          f"Flags: {len(je['risk_flags'])} -> {', '.join(je['risk_flags'])}")
